package com.bqsqwad.heartbreakhealer.feature.entertainment

internal object StoryLibraryBatch111 {
    val stories = listOf(
        StorySeries(
            id = "the_workshop_of_lost_instructions",
            title = "The Workshop of Lost Instructions",
            tagline = "A forgotten set of plans brings neighbours together to restore a useful community invention.",
            parts = listOf(
                StoryPart(1, "The Empty Drawer", listOf("When the community workshop reopened after repairs, the volunteers discovered that the instruction drawer was empty. The old manuals for garden tools, sewing machines, and wooden projects had disappeared during the move.", "Mira, a student who volunteered on Saturdays, worried that beginners would no longer know how to use the equipment safely. She suggested making new guides rather than guessing how the old ones had worked.", "The workshop coordinator agreed. Every guide would be checked by an experienced adult before it was displayed.")),
                StoryPart(2, "A Box of Clues", listOf("While sorting donated notebooks, Mira found a box labelled 'Plans—please keep'. Inside were sketches, measurements, and notes written by former volunteers.", "Some pages were faded, and others described projects that had changed over time. Mira and her friend Daniel separated the material into confirmed instructions, unfinished ideas, and records that needed checking.", "They learned that keeping uncertainty visible was better than turning an old guess into a new rule.")),
                StoryPart(3, "The First Guide", listOf("Their first project was a simple wooden book stand. The sketch showed the shape, but not the order in which the pieces should be joined.", "A carpenter named Mr Bello reviewed the drawing and demonstrated the safe sequence using prepared pieces. Mira wrote down each stage in plain language.", "Daniel added labelled pictures, while another volunteer checked that the measurements matched the finished example.")),
                StoryPart(4, "Questions from Beginners", listOf("At the next open afternoon, two younger visitors tried the guide. They understood the pictures but found one instruction confusing.", "Instead of blaming the readers, Mira asked them to explain what they thought the sentence meant. Their answers revealed that the wording could be clearer.", "The team rewrote the step and added a note explaining which tools required adult supervision.")),
                StoryPart(5, "The Missing Page", listOf("A retired volunteer visited and recognised the handwriting on one of the old sketches. She remembered that a page had been stored separately because it contained an important correction.", "The page was found in a folder of meeting notes. It showed that an earlier measurement had been changed after a test build.", "The students updated the guide and added a revision date, making it clear which version was current.")),
                StoryPart(6, "A Shelf of Skills", listOf("As the guides grew, the workshop created a shelf for them. Each folder had a title, a simple difficulty label, a safety review date, and the name of the adult who checked it.", "Mira suggested a sign-out sheet so visitors could tell the volunteers which instructions they had used and where they had become stuck.", "The shelf became a place where people could share improvements without quietly replacing someone else's work.")),
                StoryPart(7, "The Unfinished Project", listOf("One sketch showed a rainwater gauge intended for the community garden. Its final page was missing, and no one could confirm whether the design had ever been tested.", "The coordinator decided not to publish it as a ready-to-build guide. Instead, the team displayed it under 'Ideas to investigate' and invited a qualified volunteer to review it.", "Mira realised that a responsible archive sometimes protects people by saying what is not yet known.")),
                StoryPart(8, "A New Set of Hands", listOf("A family new to the neighbourhood arrived for the open afternoon. Their daughter, Leila, wanted to learn how to mend a torn library bag.", "A volunteer demonstrated the sewing machine and stayed beside her while she practised on scrap fabric. Mira used the new guide to explain the names of the parts.", "Leila finished a neat repair and asked whether she could help make the next guide easier for children to understand.")),
                StoryPart(9, "The Workshop Day", listOf("At the annual workshop day, the team displayed the old sketches beside the updated instructions. Visitors could see how an idea changed after careful testing and review.", "Former volunteers recognised their contributions, while new visitors added suggestions to a feedback notebook. The coordinator thanked everyone who had checked a detail rather than assuming it was correct.", "The workshop also announced monthly beginner sessions led by trained adults.")),
                StoryPart(10, "Instructions That Stay Alive", listOf("Mira placed the latest guide in its folder and added a note about how future volunteers could suggest changes. The archive was no longer a box of mysterious papers; it was a growing record of shared learning.", "The rainwater gauge remained an unfinished idea until its design could be reviewed and tested properly. That decision became one of the workshop's most valued examples of care.", "When Mira left that evening, Leila was helping label the next folder. The workshop had recovered more than its instructions: it had built a habit of learning together."))
            )
        )
    )
}
